grader.tests:
assert order({})==[]
assert order({'b':['a'],'d':['b'],'c':[]})==['a','b','c','d']
a={'b':['a','a']}
assert order(a)==['a','b'] and a=={'b':['a','a']}
for d in ({'x':['x']},{'a':['b'],'b':['a']}):
    try: order(d)
    except ValueError: pass
    else: raise AssertionError('cycle accepted')

a={'db':{'port':1,'hosts':['a']},'x':3}
b={'db':{'port':2},'x':None}
r=merge(a,b)
assert r=={'db':{'port':2,'hosts':['a']},'x':None}
r['db']['hosts'].append('z')
assert a['db']['hosts']==['a']
assert b=={'db':{'port':2},'x':None}
assert merge({'a':[1]},{'a':[2]})=={'a':[2]}

